if(spec.sidewalk)this.curbs(w,points,width,walk,curb,.13,.38);else if(path.type!=='gravel')for(const side of [-1,1])this.ribbon(w,points,.04,side*(width/2-.12),this.v.mat('#e0dfd0'),.16);
